package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_BOTTOM;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_END;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_LEFT;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_START;
import static com.android.SdkConstants.ATTR_LAYOUT_MARGIN_TOP;
import static com.android.SdkConstants.ATTR_PADDING;
import static com.android.SdkConstants.ATTR_PADDING_BOTTOM;
import static com.android.SdkConstants.ATTR_PADDING_END;
import static com.android.SdkConstants.ATTR_PADDING_LEFT;
import static com.android.SdkConstants.ATTR_PADDING_RIGHT;
import static com.android.SdkConstants.ATTR_PADDING_START;
import static com.android.SdkConstants.ATTR_PADDING_TOP;
import static com.android.SdkConstants.ANDROID_URI;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class RtlDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
            "RtlSymmetry",
            "Padding and margin symmetry",
            "If you specify padding or margin on one side of a layout, ...",
            Category.RTL,
            5,
            Severity.WARNING,
            new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final Collection<String> ATTRIBUTES = Arrays.asList(
            ATTR_PADDING_LEFT,
            ATTR_PADDING_RIGHT,
            ATTR_PADDING_START,
            ATTR_PADDING_END,
            ATTR_LAYOUT_MARGIN_LEFT,
            ATTR_LAYOUT_MARGIN_RIGHT,
            ATTR_LAYOUT_MARGIN_START,
            ATTR_LAYOUT_MARGIN_END
    );

    @Override
    public Collection<String> getApplicableAttributes() {
        return ATTRIBUTES;
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String name = attribute.getLocalName();
        if (!ANDROID_URI.equals(attribute.getNamespaceURI())) {
            return;
        }

        String counterpart;
        String all;
        switch (name) {
            case ATTR_PADDING_LEFT:
            case ATTR_PADDING_RIGHT:
                counterpart = name.equals(ATTR_PADDING_LEFT) ? ATTR_PADDING_RIGHT : ATTR_PADDING_LEFT;
                all = ATTR_PADDING;
                break;
            case ATTR_PADDING_START:
            case ATTR_PADDING_END:
                counterpart = name.equals(ATTR_PADDING_START) ? ATTR_PADDING_END : ATTR_PADDING_START;
                all = ATTR_PADDING;
                break;
            case ATTR_LAYOUT_MARGIN_LEFT:
            case ATTR_LAYOUT_MARGIN_RIGHT:
                counterpart = name.equals(ATTR_LAYOUT_MARGIN_LEFT) ? ATTR_LAYOUT_MARGIN_RIGHT : ATTR_LAYOUT_MARGIN_LEFT;
                all = ATTR_LAYOUT_MARGIN;
                break;
            case ATTR_LAYOUT_MARGIN_START:
            case ATTR_LAYOUT_MARGIN_END:
                counterpart = name.equals(ATTR_LAYOUT_MARGIN_START) ? ATTR_LAYOUT_MARGIN_END : ATTR_LAYOUT_MARGIN_START;
                all = ATTR_LAYOUT_MARGIN;
                break;
            default:
                return;
        }

        Element element = attribute.getOwnerElement();
        if (!element.hasAttributeNS(ANDROID_URI, counterpart)
                && !element.hasAttributeNS(ANDROID_URI, all)) {
            String message = String.format(
                    "To maintain symmetry, add %1$s in addition to %2$s (or use %3$s)",
                    counterpart, name, all);
            context.report(ISSUE, attribute, context.getLocation(attribute), message);
        }
    }
}
```

