            "RtlSymmetry", //$NON-NLS-1$
            "Padding and margin symmetry",
            "If you specify padding or margin on the left side of a layout, you should probably also specify padding on the right side (and vice versa) for right-to-left layout symmetry.",
            Category.RTL,
            5,
            Severity.WARNING,
            IMPLEMENTATION);

    private static final List<String> ATTRIBUTES = Arrays.asList(
            ATTR_PADDING_LEFT,
            ATTR_PADDING_RIGHT,
            ATTR_PADDING_START,
            ATTR_PADDING_END,
            ATTR_LAYOUT_MARGIN_LEFT,
            ATTR_LAYOUT_MARGIN_RIGHT,
            ATTR_LAYOUT_MARGIN_START,
            ATTR_LAYOUT_MARGIN_END);

    @Override
    public Collection<String> getApplicableAttributes() {
        return ATTRIBUTES;
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String name = attribute.getLocalName();
        String counterpart;
        String all;
        String horizontal;

        if (name.equals(ATTR_PADDING_LEFT)) {
            counterpart = ATTR_PADDING_RIGHT;
            all = ATTR_PADDING;
            horizontal = ATTR_PADDING_HORIZONTAL;
        } else if (name.equals(ATTR_PADDING_RIGHT)) {
            counterpart = ATTR_PADDING_LEFT;
            all = ATTR_PADDING;
            horizontal = ATTR_PADDING_HORIZONTAL;
        } else if (name.equals(ATTR_PADDING_START)) {
            counterpart = ATTR_PADDING_END;
            all = ATTR_PADDING;
            horizontal = ATTR_PADDING_HORIZONTAL;
        } else if (name.equals(ATTR_PADDING_END)) {
            counterpart = ATTR_PADDING_START;
            all = ATTR_PADDING;
            horizontal = ATTR_PADDING_HORIZONTAL;
        } else if (name.equals(ATTR_LAYOUT_MARGIN_LEFT)) {
            counterpart = ATTR_LAYOUT_MARGIN_RIGHT;
            all = ATTR_LAYOUT_MARGIN;
            horizontal = ATTR_LAYOUT_MARGIN_HORIZONTAL;
        } else if (name.equals(ATTR_LAYOUT_MARGIN_RIGHT)) {
            counterpart = ATTR_LAYOUT_MARGIN_LEFT;
            all = ATTR_LAYOUT_MARGIN;
            horizontal = ATTR_LAYOUT_MARGIN_HORIZONTAL;
        } else if (name.equals(ATTR_LAYOUT_MARGIN_START)) {
            counterpart = ATTR_LAYOUT_MARGIN_END;
            all = ATTR_LAYOUT_MARGIN;
            horizontal = ATTR_LAYOUT_MARGIN_HORIZONTAL;
        } else if (name.equals(ATTR_LAYOUT_MARGIN_END)) {
            counterpart = ATTR_LAYOUT_MARGIN_START;
            all = ATTR_LAYOUT_MARGIN;
            horizontal = ATTR_LAYOUT_MARGIN_HORIZONTAL;
        } else {
            return;
        }

        Element element = attribute.getOwnerElement();
        if (!element.hasAttributeNS(ANDROID_URI, counterpart)
                && !element.hasAttributeNS(ANDROID_URI, all)
                && !element.hasAttributeNS(ANDROID_URI, horizontal)) {
            String message = String.format(
                    "When you define %1$s you should probably also define %2$s for right-to-left symmetry",
                    name, counterpart);
            context.report(ISSUE, attribute, context.getLocation(attribute), message);
        }
    }
}
